  1→// 通用 Android 性能分析平台 · P0 领域模型地基
  2→//
  3→// 依据:
  4→//   - docs/analysis-framework-design.md §5 (Run = raw + core + detail) / §6 (分层 + skill 架构)
  5→//   - docs/performance-platform-requirements-v2.md §2 (领域模型) / §8 (insights) / §11 (命名迁移)
  6→//
  7→// 命名约定 (硬约束):
  8→//   - 无 Maple 关键字; pdata/.pdata 统一为 UnityProfilerData, 源 id = 'unity_profiler'。
  9→//   - core 用"指标袋 metrics[]"承载跨源可比指标, 禁止 il2cppBasePct 这类用例耦合的硬编码列。
 10→//   - detail 为 schemaless 原样留档, 新维度进 detail, 不撑爆 core。
 11→
 12→// ============================================================
 13→// 源标识
 14→// ============================================================
 15→
 16→/** 数据源 id。已知三源 + 可扩展 (新增源遵循"1 Provider + 1 单源 skill")。 */
 17→export type SourceId = 'unity_profiler' | 'simpleperf' | 'perfetto' | (string & {});
 18→
 19→/** 已落地的三源 (用于遍历 / 校验)。 */
 20→export const KNOWN_SOURCE_IDS = ['unity_profiler', 'simpleperf', 'perfetto'] as const;
 21→
 22→// ============================================================
 23→// core —— 归一化指标 (统一词汇表)
 24→// ============================================================
 25→
 26→/** 帧口径: 不同源各一条, 禁止默认直比 (Choreographer ≠ PlayerLoop)。 */
 27→export type FrameDefinition = 'playerloop' | 'choreographer' | 'frametimeline' | (string & {});
 28→
 29→export type MetricUnit = 'ms' | '%' | 'pp' | 'mhz' | 'count' | 'mb' | 'bytes' | (string & {});
 30→
 31→export type Confidence = 'high' | 'medium' | 'low';
 32→
 33→/**
 34→ * 指标袋的一行。加指标 = 多一行, 不改表结构。
 35→ * key 采用统一命名空间, 例: 'cpu.lib.libil2cpp.pct' / 'frame.p95Ms' / 'system.cpuFreqAvgMhz'。
 36→ */
 37→export interface Metric {
 38→  key: string;
 39→  value: number;
 40→  unit: MetricUnit;
 41→  source: SourceId;
 42→  confidence?: Confidence;
 43→}
 44→
 45→/** 帧分布 (每源一条, 显式标注口径)。 */
 46→export interface FrameStat {
 47→  source: SourceId;
 48→  frameDefinition: FrameDefinition;
 49→  p50Ms: number;
 50→  p95Ms: number;
 51→  p99Ms: number;
 52→  fps: number;
 53→  /** 慢帧占比 (0-1 或 %, 由 source 决定, 文案需注明)。 */
 54→  slowFrameRate: number;
 55→}
 56→
 57→/** 线程调度状态 (主要来自 perfetto)。 */
 58→export interface ThreadStat {
 59→  source: SourceId;
 60→  name: string;
 61→  runningPct: number;
 62→  runnablePct: number;
 63→  sleepingPct: number;
 64→}
 65→
 66→/** 系统级状态 (频率 / 降频 / GPU / binder / 内存)。字段可缺失 → 降级。 */
 67→export interface SystemStat {
 68→  cpuFreqAvgMhz?: number;
 69→  cpuThrottled?: boolean;
 70→  thermalC?: number;
 71→  gpuBusyPct?: number;
 72→  binder?: { count: number; avgMs: number };
 73→  pssMb?: number;
 74→}
 75→
 76→/** 跨源可信度: 帧偏差超阈值即告警。 */
 77→export interface ProfileConfidence {
 78→  perFrameAlignmentOk: boolean;
 79→  notes: string[];
 80→}
 81→
 82→/** 当前归一化逻辑版本。core 由 raw 重算时据此判断是否需要重解析。 */
 83→export const PERF_PROFILE_SCHEMA_VERSION = 1;
 84→
 85→/** core —— 物化入库的归一化视图, 服务于单次展示 / 列表 / 趋势。 */
 86→export interface PerfProfileCore {
 87→  schemaVersion: number;
 88→  metrics: Metric[];
 89→  frame: FrameStat[];
 90→  threads: ThreadStat[];
 91→  system: SystemStat;
 92→  confidence: ProfileConfidence;
 93→}
 94→
 95→// ============================================================
 96→// CallTree —— 三源共享的"以已知根为起点的每线程调用树" (contract §1.5)
 97→//
 98→// 决策 8: 三源都产"以已知根为起点的每线程调用树", 统一结构, 放 detail.<source>.callTrees。
 99→// 这棵树同时支撑单源热点(self 最高节点) / anchor(选定节点 totalPct) / 对比差分(同名节点配对做减法)。
100→// 无树的新源 (Thermal/PMU 等) 不产即可, 不破坏可插拔。
101→// ============================================================
102→
103→/** 节点层次标签 (主要 simpleperf 用; unity/perfetto 可不填)。 */
104→export type CallTreeLayer = 'business' | 'engine' | 'runtime' | 'noise' | (string & {});
105→
106→/** 统一调用树节点。三源 detail 都放一份, 字段名一致 (便于对比层按名配对)。 */
107→export interface CallTreeNode {
108→  name: string;
109→  /** 自身耗时 (不含子树)。 */
110→  selfMs?: number;
111→  selfPct?: number;
112→  /** 子树总耗时。 */
113→  totalMs?: number;
114→  totalPct?: number;
115→  /** 层次标签 (simpleperf 用; 业务/引擎/运行时/噪音)。 */
116→  layer?: CallTreeLayer;
117→  children: CallTreeNode[];
118→}
119→
120→/** 一棵以某根 (PlayerLoop / 线程入口) 为起点的调用树。挂在 detail.<source>.callTrees[]。 */
121→export interface CallTree {
122→  /** 树所属线程名。 */
123→  thread: string;
124→  /** 可选: 这棵树的取样来源 (如 'worstFrame#123' / 'medianFrame' / 'thread-total')。 */
125→  label?: string;
126→  root: CallTreeNode;
127→}
128→
129→// ============================================================
130→// detail —— schemaless 各源富数据 (不归一化)
131→// ============================================================
132→
133→export interface PerfettoThreadSchedEntry {
134→  name?: string;
135→  count?: number;
136→  runningPct?: number;
137→  runnablePct?: number;
138→  sleepingPct?: number;
139→  totalNs?: number;
140→  tid?: number;
141→  commName?: string;
142→  identifiedBy?: string;
143→  [k: string]: unknown;
144→}
145→
146→export interface PerfettoAoeHotSlice {
147→  label?: string;
148→  pattern?: string;
149→  count?: number;
150→  totalMs?: number;
151→  avgMs?: number;
152→  maxMs?: number;
153→  totalPct?: number;
154→  selfMs?: number;
155→  selfPct?: number;
156→  [k: string]: unknown;
157→}
158→
159→export interface PerfettoThermalInfo {
160→  beforeC?: number | null;
161→  afterC?: number | null;
162→  deltaC?: number | null;
163→  [k: string]: unknown;
164→}
165→
166→export interface PerfettoCpuThrottlingEntry {
167→  cpu?: number;
168→  avgMhz?: number | null;
169→  maxMhz?: number | null;
170→  cpuinfoMaxMhz?: number | null;
171→  reachVsCpuinfoPct?: number | null;
172→  reachPct?: number | null;
173→  [k: string]: unknown;
174→}
175→
176→export interface PerfettoThrottling {
177→  level?: string;
178→  confirmedAvailable?: boolean;
179→  thermal?: PerfettoThermalInfo | null;
180→  collectionManifest?: Record<string, unknown> | null;
181→  perCpu?: PerfettoCpuThrottlingEntry[];
182→  bigCoreReachPct?: number | null;
183→  [k: string]: unknown;
184→}
185→
186→export interface PerfettoBinderPeerEntry {
187→  name?: string;
188→  serverProcess?: string;
189→  count?: number;
190→  avgMs?: number;
191→  maxMs?: number;
192→  totalMs?: number;
193→  [k: string]: unknown;
194→}
195→
196→export interface PerfettoBinderPeers {
197→  byTxnName?: PerfettoBinderPeerEntry[];
198→  byServerProcess?: PerfettoBinderPeerEntry[];
199→  [k: string]: unknown;
200→}
201→
202→export interface PerfettoGcAllocModule {
203→  module?: string;
204→  pattern?: string;
205→  moduleSliceCount?: number;
206→  allocCount?: number;
207→  allocBytes?: number;
208→  allocMb?: number;
209→  allocPerFrame?: number;
210→  topAllocSlices?: Array<Record<string, unknown>>;
211→  [k: string]: unknown;
212→}
213→
214→export interface PerfettoOffCpuAttribution {
215→  totalOffCpuMs?: number;
216→  byState?: Array<Record<string, unknown>>;
217→  blockedReasonTopK?: Array<Record<string, unknown>>;
218→  wakerTopK?: Array<Record<string, unknown>>;
219→  [k: string]: unknown;
220→}
221→
222→export interface PerfettoDetail {
223→  profileWindow?: { startNs?: string; endNs?: string; durMs?: number; [k: string]: unknown };
224→  parseOptions?: Record<string, unknown>;
225→  threadsSched?: Record<string, PerfettoThreadSchedEntry>;
226→  threadsSchedList?: PerfettoThreadSchedEntry[];
227→  threadSchedView?: {
228→    primary?: PerfettoThreadSchedEntry[];
229→    jobWorkerPool?: PerfettoThreadSchedEntry | null;
230→    jobWorkers?: PerfettoThreadSchedEntry[];
231→    others?: PerfettoThreadSchedEntry[];
232→    [k: string]: unknown;
233→  };
234→  aoeHotSlices?: PerfettoAoeHotSlice[];
235→  throttling?: PerfettoThrottling | null;
236→  binderPeers?: PerfettoBinderPeers;
237→  gcAllocByModule?: PerfettoGcAllocModule[];
238→  offCpuAttribution?: PerfettoOffCpuAttribution;
239→  frameAnalysis?: FrameAnalysis;
240→  frameTimeline?: unknown;
241→  machineState?: Record<string, unknown>;
242→  offCpu?: Record<string, unknown>;
243→  callTrees?: CallTree[];
244→  [k: string]: unknown;
245→}
246→
247→/** 各源专属富数据/产物指针。新维度进这里, 永不撑爆 core。 */
248→export interface SourceDetail {
249→  unity_profiler?: unknown; // frameAnalysis / markers / callTree …
250→  simpleperf?: unknown;     // folded / flamegraphPath / 完整函数表 …
251→  perfetto?: PerfettoDetail; // frameAnalysis / sqlResults / surfaceFlinger …
252→  [k: string]: unknown;
253→}
254→
255→// ============================================================
256→// frameAnalysis — L1–L3 帧分析（ingest 契约，见 docs/frame-analysis-data-contract.md）
257→// ============================================================
258→
259→export type DeviceTier = 'high' | 'mid' | 'low' | 'unknown';
260→
261→export interface FrameAnalysisSummary {
262→  count: number;
263→  p50Ms: number;
264→  p95Ms: number;
265→  p99Ms: number;
266→  fps: number;
267→  slowFrameRate33?: number;
268→  slowFrameRate50?: number;
269→  worstFrameIndex?: number;
270→  medianFrameIndex?: number;
271→  p95FrameIndex?: number;
272→  frameIndexOffset?: number;
273→}
274→
275→export interface SlowFrameEntry {
276→  frameIndex: number;
277→  ms: number;
278→  rank: number;
279→}
280→
281→export interface TraceSegment {
282→  startFrame: number;
283→  endFrame: number;
284→  label: string;
285→  source: 'marker' | 'meta' | 'inferred' | 'manual' | 'combined-profile';
286→  confidence?: 'high' | 'medium' | 'low';
287→}
288→
289→export interface FrameContext {
290→  frameIndex: number;
291→  labels: Record<string, string>;
292→  evidence?: Array<{
293→    classifierId: string;
294→    markers?: string[];
295→    confidence?: 'high' | 'inferred';
296→  }>;
297→}
298→
299→export interface ContextSummary {
300→  byClassifier: Record<string, number>;
301→  segments?: TraceSegment[];
302→}
303→
304→export interface WatchTargetMatch {
305→  type: 'marker' | 'slice';
306→  patterns: string[];
307→}
308→
309→export interface WatchRule {
310→  id?: string;
311→  ref?: string;
312→  when?: string;
313→  expr?: string;
314→  params?: Record<string, number>;
315→  severity?: 'warn' | 'critical';
316→  message?: string;
317→}
318→
319→export interface WatchTarget {
320→  id: string;
321→  knowledgeRef?: string;
322→  match: {
323→    unity?: WatchTargetMatch;
324→    perfetto?: WatchTargetMatch;
325→  };
326→  playerLoopPhase?: string[];
327→  callPath?: string[];
328→  notes?: string;
329→  rules: WatchRule[];
330→}
331→
332→export interface WatchSpec {
333→  version: number;
334→  schemaRef: string;
335→  preset?: string;
336→  deviceTier?: DeviceTier;
337→  frameBudgetMs: number;
338→  targets: WatchTarget[];
339→  specPath?: string;
340→}
341→
342→export interface MarkerFrameSeries {
343→  targetId: string;
344→  timings: (number | null)[];
345→  presentCount: number;
346→  summary?: {
347→    medianMs: number;
348→    p95Ms: number;
349→    maxMs: number;
350→  };
351→}
352→
353→export interface FlaggedFrame {
354→  frameIndex: number;
355→  targetId: string;
356→  ruleId: string;
357→  severity: 'warn' | 'critical';
358→  actualMs: number;
359→  frameMs?: number;
360→  context?: Record<string, string>;
361→  deviceTier?: DeviceTier;
362→  message: string;
363→}
364→
365→/** detail.<source>.frameAnalysis — L1 帧基础设施 + L1.5 context + L2 watchSpec 快照 + L3 派生 */
366→export interface FrameAnalysis {
367→  frameDefinition: FrameDefinition;
368→  thread?: string;
369→  summary: FrameAnalysisSummary;
370→  timings: number[];
371→  slowFrames?: SlowFrameEntry[];
372→  frameTrees?: CallTree[];
373→  segments?: TraceSegment[];
374→  contextByFrame?: FrameContext[];
375→  contextSummary?: ContextSummary;
376→  watchSpec?: WatchSpec;
377→  series?: MarkerFrameSeries[];
378→  flags?: FlaggedFrame[];
379→}
380→
381→// ============================================================
382→// raw —— 原始文件指针 (真相源)
383→// ============================================================
384→
385→/** 原始文件指针, 引用统一 Asset 存储 (assets 表)。 */
386→export interface RawAssetRef {
387→  source: SourceId;
388→  /** assets.id; 适配旧表时可能仅有 localPath。 */
389→  assetId?: string;
390→  /** 角色: perf_data | binary_cache | unity_profiler_data | pftrace | meta … */
391→  role: string;
392→  fileName?: string;
393→  localPath?: string;
394→  sha256?: string;
395→}
396→
397→// ============================================================
398→// PerfProfile = raw + core + detail
399→// ============================================================
400→
401→export interface PerfProfile {
402→  raw: RawAssetRef[];
403→  core: PerfProfileCore;
404→  detail: SourceDetail;
405→}
406→
407→// ============================================================
408→// Run —— 一次采集 = 出数据的单元
409→// ============================================================
410→
411→export type RunStatus = 'pending' | 'parsing' | 'ready' | 'failed';
412→
413→export interface RunMeta {
414→  device?: string;
415→  scene?: string;
416→  projectName?: string;
417→  version?: string;
418→  branch?: string;
419→  createdBy?: string;
420→  notes?: string;
421→  durationSec?: number;
422→  frameCount?: number;
423→  /** Unity skill / preprocess 目标帧率 (默认 60)。 */
424→  targetFps?: number;
425→  /** clock_monotonic 对齐窗口 (text 存 bigint)。 */
426→  monoNsStart?: string;
427→  monoNsEnd?: string;
428→  /** 高端 / 中端 / 低端 / unknown — 见 docs/device-tier-map.json */
429→  deviceTier?: DeviceTier;
430→}
431→
432→export interface Run {
433→  id: string;
434→  label?: string;
435→  /** 本 Run 实际含哪些源。 */
436→  sources: SourceId[];
437→  status: RunStatus;
438→  meta: RunMeta;
439→  profile: PerfProfile;
440→  createdAt: number;
441→  completedAt?: number;
442→  error?: string;
443→  /** 过渡期标识: 该 Run 由哪个旧表的哪行适配而来 (只读适配产物)。 */
444→  legacy?: { table: string; id: string };
445→}
446→
447→// ============================================================
448→// Analysis —— 分析任务 (single / compare)
449→// ============================================================
450→
451→export type AnalysisMode = 'single' | 'compare';
452→export type AnalysisStatus = 'pending' | 'queued' | 'running' | 'completed' | 'failed';
453→
454→export interface Analysis {
455→  id: string;
456→  mode: AnalysisMode;
457→  /** single: 1 个 runId; compare: 2 个 [base, current]。 */
458→  runIds: string[];
459→  status: AnalysisStatus;
460→  /** 解读用 skill: unity-profiler-analysis / simpleperf-analysis / perfetto-analysis / cross-source-analysis。 */
461→  skill?: string;
462→  createdAt: number;
463→  completedAt?: number;
464→  error?: string;
465→  reportId?: string;
466→  legacy?: { table: string; id: string };
467→}
468→
469→// ============================================================
470→// Report —— 分析产出 (结论先行 + insights), 挂在 Analysis 上
471→// ============================================================
472→
473→export type InsightSeverity = 'critical' | 'high' | 'medium' | 'low' | 'info';
474→
475→/** 证据条目: 按源通用命名 (去用例化, 不写 <source>Evidence 的硬编码字段)。 */
476→export interface InsightEvidence {
477→  source: SourceId;
478→  detail: string;
479→}
480→
481→/** 单条洞见, 对应需求 §8 的 insights 结构 (去 Maple 化)。 */
482→export interface Insight {
483→  id: string;
484→  severity: InsightSeverity;
485→  confidence: Confidence;
486→  sources: SourceId[];
487→  evidence?: InsightEvidence[];
488→  /** 普通话结论先行。 */
489→  conclusion: string;
490→  recommendation?: string;
491→}
492→
493→export interface Report {
494→  id: string;
495→  analysisId: string;
496→  /** 结论先行: 页面最顶部的一句普通话总结。 */
497→  headline?: string;
498→  markdown: string;
499→  insights: Insight[];
500→  createdAt: number;
501→}
502→
503→// ============================================================
504→// Provider 接口 (P1 落地的签名, P0 仅预声明地基)
505→// ============================================================
506→
507→/**
508→ * 某数据源的解析器 (出数据, 确定性代码)。
509→ * P1 把 3 个解析器包成 Provider, 各产出 PerfProfile 片段, 由上层合并入同一 Run。
510→ * P0 仅声明接口形状, 不实现; 便于后续按此签名落地。
511→ */
512→export interface PerfProvider {
513→  readonly source: SourceId;
514→  /** 该源能解析的 raw 角色 (供采集/校验阶段路由文件)。 */
515→  readonly acceptsRoles: string[];
516→  /** 解析 raw → 该源的 PerfProfile 片段 (core 片段 + detail 片段)。 */
517→  parse(input: ProviderParseInput): Promise<ProviderParseResult>;
518→}
519→
520→export interface ProviderParseInput {
521→  runId: string;
522→  raw: RawAssetRef[];
523→  /** 工具链/符号路径等, 由 Provider 自定; 保持 schemaless。 */
524→  options?: Record<string, unknown>;
525→}
526→
527→export interface ProviderParseResult {
528→  source: SourceId;
529→  metrics: Metric[];
530→  frame: FrameStat[];
531→  threads: ThreadStat[];
532→  /** 该源能贡献的 system 字段 (合并时按源覆盖)。 */
533→  system: Partial<SystemStat>;
534→  detail: unknown;
535→  notes: string[];
536→}
537→
